/* منصة لغتي — واجهة الطالب والمعلم. مفاتيح الإجابة لا توزع ضمن الموقع. */
'use strict';
const ENDPOINT='https://script.google.com/macros/s/AKfycbwiIyjibZb4kmBaYQHnoVLCMQmZqjFwKXbaeAI0y5X0CywsTC09unilyabsNFpZQ54i/exec';
const C=window.NAFIS_CATALOG, main=document.querySelector('main'), dialog=document.querySelector('dialog');
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ar=n=>Number(n).toLocaleString('ar-SA'), when=s=>new Date(s).toLocaleString('ar-SA',{dateStyle:'short',timeStyle:'short'});
const uid=()=>crypto.randomUUID();
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
function write(key,value){localStorage.setItem(key,JSON.stringify(value));}
let profile=read('nafis-profile-v2',null), attempt=read('nafis-active-v2',null), results=read('nafis-results-v2',[]), index=0, busy=false, tick, report=[], teacherSession=null, routeSeq=0;
let drafts=read('nafis-drafts-v3',{});
function draftKey(a){return JSON.stringify([a.profile.studentId,a.examId,a.version]);}
if(attempt && !results.some(r=>r.attemptId===attempt.attemptId)){
 try{drafts[draftKey(attempt)]=attempt;write('nafis-drafts-v3',drafts);localStorage.removeItem('nafis-active-v2');}catch{}
}
function savedAttempt(id){return Object.values(drafts).find(a=>a.profile.studentId===profile?.studentId&&a.examId===id&&a.version===C.exams.find(e=>e.id===id)?.version);}
function quizLink(a){return '#quiz/'+encodeURIComponent(a.examId);}
function returnLink(a){const e=C.exams.find(e=>e.id===a.examId);return e?.kind==='reading'?'#read/'+e.passageIds[0]:'#exams';}
function questionPassage(a,q){
 const e=C.exams.find(e=>e.id===a.examId);if(e?.kind!=='skill')return a.passage;
 const title=q.question.match(/^في نص «([^»]+)»/u)?.[1];
 const sections=a.passage.split(/(?=【)/u);return sections.find(t=>title&&t.startsWith('【'+title+'】'))||a.passage;
}
function notify(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(notify.t);notify.t=setTimeout(()=>$('#toast').hidden=true,5000);}
function openDialog(html){$('#dialog-body').innerHTML=html;dialog.showModal();}
$('.close').onclick=()=>dialog.close();
function paragraphs(text){return String(text).split('\n').filter(Boolean).map(p=>p.startsWith('【')?'<h2>'+esc(p.replace(/[【】]/g,''))+'</h2>':'<p>'+esc(p)+'</p>').join('');}
function btn(text,attrs='',type=''){return '<button class="btn '+type+'" '+attrs+'>'+text+'</button>';}
function title(eyebrow,heading,description){return '<div class="page-title"><div class="eyebrow">'+eyebrow+'</div><h1>'+heading+'</h1><p>'+description+'</p></div>';}
function summaryCard(e,i){const done=results.some(r=>r.examId===e.id&&r.studentId===profile?.studentId);return '<article class="card"><div class="between full"><span class="num">'+ar(i+1)+'</span>'+(done?'<span class="badge">أنجزت محاولة</span>':'<span class="badge gold">'+(e.kind==='simulation'?'محاكاة تدريبية':e.kind==='reading'?'قراءة وفهم':'تدريب مهاري')+'</span>')+'</div><h3>'+esc(e.title)+'</h3><p>'+esc(e.description)+'</p><div class="meta"><span>'+ar(e.count)+' أسئلة</span><span>·</span><span>'+ar(e.minutes)+' دقيقة مقترحة</span></div>'+btn('ابدأ التدريب ←','data-start="'+e.id+'"')+'</article>';}
function profileForm(next){openDialog('<h2>نتعرف عليك أولًا</h2><p class="hint">أدخل بياناتك كما يعرفها المعلم. رمز الطالب رمز دراسي تختاره مع معلمك، وليس رقم الهوية.</p><form id="profile-form"><div class="field"><label for="pname">اسم الطالب</label><input id="pname" required maxlength="120" autocomplete="name" value="'+esc(profile?.name||'')+'" placeholder="اسمك الثلاثي"></div><div class="field"><label for="pclass">الفصل</label><input id="pclass" required maxlength="40" value="'+esc(profile?.classroom||'')+'" placeholder="السادس أ"></div><div class="field"><label for="pid">رمز الطالب</label><input id="pid" required maxlength="40" pattern="[A-Za-z0-9][A-Za-z0-9_.-]*" dir="ltr" value="'+esc(profile?.studentId||'')+'" placeholder="6A-01"><small class="hint">حروف إنجليزية وأرقام. استخدم الرمز نفسه في كل مرة وعلى أجهزتك.</small></div><p id="profile-error" class="error"></p>'+btn('حفظ ومتابعة','type="submit"','full')+'</form>');
$('#profile-form').onsubmit=e=>{e.preventDefault();const p={name:$('#pname').value.trim(),classroom:$('#pclass').value.trim(),studentId:$('#pid').value.trim()};if(!p.name||!p.classroom)return;try{write('nafis-profile-v2',p);profile=p;dialog.close();next?next():render();}catch{$('#profile-error').textContent='فعّل تخزين بيانات الموقع في المتصفح لحفظ محاولتك بأمان.';}};}
function icon(name){const paths={book:'M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4z M20 4h-4a3 3 0 0 0-3 3v14a4 4 0 0 1 4-2h3z',teacher:'M4 4h16v12H4z M8 21l4-5 4 5 M8 8h8 M8 12h4',chart:'M4 20V4 M4 20h17 M8 16v-5 M13 16V7 M18 16V3',words:'M4 5h16 M7 5c0 7 5 12 11 14 M17 5C16 12 11 17 5 19',print:'M7 8V3h10v5 M7 17H4V9h16v8h-3 M7 14h10v7H7z',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',video:'M3 5h18v14H3z M10 8l5 4-5 4z',chat:'M3 4h18v13H8l-5 4z M7 8h10 M7 12h6',refresh:'M20 7v5h-5 M4 17v-5h5 M5 7a8 8 0 0 1 13-2l2 3 M4 16l2 3a8 8 0 0 0 13-2',exit:'M9 4H4v16h5 M9 12h12 M17 8l4 4-4 4'};return '<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+(paths[name]||paths.book)+'"/></svg>';}
function home(){return '<section class="hero"><div class="hero-copy"><div class="eyebrow">النسخة الثانية · التحديث ٢</div><h1>محاكي نافس<br><span>المطور</span></h1><p>اقرأ النص، وتأمل معانيه، ثم أجب عن أسئلته. كل محاولة خطوة نحو فهم أعمق وثقة أكبر.</p><div class="actions"><a href="#exams" class="btn gold">ابدأ المحاكاة</a><a href="#words" class="btn outline">الكلمة ومرادفها وضدها</a></div></div><div class="hero-art" aria-hidden="true"><div class="reading-card"><img src="assets/nafis.jpg" alt=""><div class="eyebrow">الصف السادس الابتدائي</div><h2>أقرأ. أفهم.<br>أستنتج.</h2><div class="fake-lines"><i></i><i></i><i></i></div></div><span class="art-note">بالممارسة ينمو الفهم.</span></div></section><div class="profile"><div><strong>'+(profile?'أهلًا '+esc(profile.name):'أهلًا بك في رحلة التعلم')+'</strong><p>'+(profile?esc(profile.classroom):'الصف السادس الابتدائي · مهارات القراءة')+'</p></div>'+btn(profile?'بياناتي':'أدخل بياناتك','data-profile','light')+'</div><div class="section-head"><h2>مساحات التعلم</h2></div><div class="grid route-grid">'+[
 ['book','المحاكاة','نصوص متنوعة، ولكل نص اختبار مستقل يقيس مهارات الفهم.','#exams','اختر محاكاتك'],
 ['words','الكلمة ومرادفها وضدها','رصيد لغوي تتعلمه من المعنى والمثال، دون اختبار.','#words','اكتشف الكلمات'],
 ['chart','رحلة تقدمي','نتائج محاولاتك وإجاباتك في مكان واحد.','#progress','نتائجي']
 ].map(([i,t,d,u,b])=>'<article class="card"><span class="num">'+icon(i)+'</span><h3>'+t+'</h3><p>'+d+'</p><a class="btn light" href="'+u+'">'+b+'</a></article>').join('')+'</div><div class="section-head"><h2>روابط وموارد</h2></div>'+resources();}

function resources(){return '<div class="grid resource-cards">'+[
 ['teacher','لوحة المعلم','النتائج والمهارات وتقارير الطلاب.','#teacher','فتح لوحة المعلم'],
 ['book','الاختبارات السابقة','النسخ السابقة للتدريب والمراجعة.','#past-exams','فتح الاختبارات'],
 ['chat','قناة الواتساب','قناة التواصل والمواد التعليمية.','https://whatsapp.com/channel/0029Vb6w53QJkK75ofdFIE3M', 'فتح القناة'],
 ['video','فيديو نافس','التعريف بنافس والاستعداد للاختبار.','https://www.youtube.com/watch?v=LtZKPUhr230','مشاهدة الفيديو'],
 ['print','النسخة المطبوعة','مواد القراءة والتدريب على الورق.','https://drive.google.com/file/d/1sRCLJFeUgwPiGjNFm1d_J6YXIwJbWxvt/view','فتح النسخة'],
 ['video','طريقة التظليل','تسجيل الإجابات في ورقة الاختبار.','https://www.youtube.com/watch?v=8CDEEv6Sjgo','مشاهدة الشرح']
 ].map(([i,t,d,u,b])=>'<article class="card"><span class="num">'+icon(i)+'</span><h3>'+t+'</h3><p>'+d+'</p>'+(u?'<a class="btn light" href="'+u+'" '+(u.startsWith('https:')?'target="_blank" rel="noopener"':'')+'>'+b+'</a>':'<span class="badge gold">'+b+'</span>')+'</article>').join('')+'</div>';}

function pastExams(){return title('للمراجعة والتدريب','الاختبارات السابقة','اختر الاختبار الذي ترغب في مراجعته.')+'<div class="grid">'+Array.from({length:13},(_,i)=>'<article class="card"><span class="num">'+ar(i+1)+'</span><h3>الاختبار السابق '+ar(i+1)+'</h3><p>افتح النسخة السابقة في نافذة مستقلة.</p><a class="btn light" target="_blank" rel="noopener" href="https://aass-2008-wq.github.io/'+(i===0?'nafis-exams':'nafis-exam'+(i+1))+'/">فتح الاختبار ←</a></article>').join('')+'</div>';}
function readings(){return title('المحاكاة','اقرأ النص وأجب','اختر النص، واقرأه كاملًا، ثم أجب عن أسئلته.')+'<div class="section-head"><p>'+ar(C.passages.length)+' نصًا · '+ar(C.passages.length*8)+' سؤالًا · قصص ومعلومات وإرشادات</p></div><div class="grid">'+C.passages.map((p,i)=>'<article class="card"><div class="between full"><span class="num">'+ar(i+1)+'</span><span class="badge">'+esc(p.genre)+'</span></div><h3>'+esc(p.title)+'</h3><p>'+esc(p.text.slice(0,110))+'…</p><div class="meta">٨ أسئلة · ١٥ دقيقة مقترحة</div><a class="btn light" href="#read/'+p.id+'">قراءة النص وبدء المحاكاة</a></article>').join('')+'</div>';}
function words(){return title('رصيدي اللغوي','الكلمة ومرادفها وضدها','اقرأ الكلمة في مثالها، وتعرف معناها ومرادفها وضدها.')+'<div class="word-tools"><label for="word-search">ابحث عن كلمة أو معنى</label><input id="word-search" type="search" placeholder="اكتب الكلمة هنا"><div class="actions"><button class="btn light" data-word-kind="all">جميع الكلمات</button><button class="btn light" data-word-kind="synonym">المرادفات</button><button class="btn light" data-word-kind="opposite">الأضداد</button><button class="btn light" data-word-kind="saved">كلماتي المحفوظة</button></div></div><p id="word-count" class="hint"></p><div id="word-list" class="grid"></div>';}
let wordKind='all';
function drawWords(){const saved=read('nafis-words-v2',[]),term=($('#word-search')?.value||'').trim(),normalize=t=>t.replace(/[\u064b-\u065f]/g,'').replace(/[أإآ]/g,'ا').replace(/ى/g,'ي');const ws=(C.words||[]).filter(w=>(wordKind!=='saved'||saved.includes(w.word))&&normalize(Object.values(w).join(' ')).includes(normalize(term)));$('#word-count').textContent=ar(ws.length)+' كلمة';$('#word-list').innerHTML=ws.length?ws.map(w=>'<article class="card word-card"><div class="between full"><h3>'+esc(w.word)+'</h3><button class="word-save text-btn" data-word-save="'+esc(w.word)+'" aria-label="حفظ كلمة '+esc(w.word)+'" aria-pressed="'+saved.includes(w.word)+'">'+(saved.includes(w.word)?'★':'☆')+'</button></div>'+(wordKind!=='opposite'?'<p><span class="badge">مرادفها</span> <strong>'+esc(w.synonym)+'</strong></p>':'')+(wordKind!=='synonym'?'<p><span class="badge gold">ضدها</span> <strong>'+esc(w.opposite)+'</strong></p>':'')+'<p class="word-example">'+esc(w.example)+'</p></article>').join(''):'<div class="empty">لا توجد كلمات ضمن هذا الاختيار.</div>';document.querySelectorAll('[data-word-save]').forEach(b=>b.onclick=()=>{const list=read('nafis-words-v2',[]),v=b.dataset.wordSave;try{write('nafis-words-v2',list.includes(v)?list.filter(x=>x!==v):list.concat(v));drawWords();}catch{notify('تعذر حفظ الكلمة على الجهاز.');}});}
function skills(){return title('خطوة مركزة','تدرب على مهارتك','اختر المهارة التي تحتاج إلى تقويتها. استخدم دليلًا من النص لتبرير إجابتك، ثم راجع تفسيرها بعد التسليم.')+'<div class="notice">قد تصادف أسئلة تدربت عليها سابقًا؛ اقرأ النص مجددًا، وفسر سبب اختيارك قبل التسليم.</div><div class="grid skill-grid">'+C.skills.map((s,i)=>'<article class="card"><span class="num">'+ar(i+1)+'</span><h3>'+esc(s.label)+'</h3><p>'+esc(s.tip)+'</p>'+btn('تدرب الآن ←','data-start="SKILL-'+s.id+'"','light')+'</article>').join('')+'</div>';}
const readyExams=new Set();
async function checkReadingReady(){const button=$('[data-bank-check]');if(!button)return;const id=button.dataset.bankCheck;try{const response=await rpc({action:'ping'});if(response.availableExamIds?.includes(id)){readyExams.add(id);if(button.isConnected){button.disabled=false;button.textContent='ابدأ الاختبار';}}else if(button.isConnected)button.textContent='الاختبار قيد الإعداد';}catch{if(button.isConnected)button.textContent='تعذر التحقق من توفر الاختبار؛ حدّث الصفحة';}}
function reader(id){const p=C.passages.find(p=>p.id===id);if(!p)return notFound();return '<a href="#exams">العودة إلى المحاكاة</a><article class="reader"><span class="eyebrow">'+esc(p.genre)+'</span><h1>'+esc(p.title)+'</h1>'+paragraphs(p.text)+'</article><div class="actions">'+btn(C.exams.find(e=>e.id==='READ-'+p.id)?.requiresBankUpdate&&!readyExams.has('READ-'+p.id)?'جارٍ التحقق من توفر الاختبار…':'ابدأ الاختبار','data-start="READ-'+p.id+'"'+(C.exams.find(e=>e.id==='READ-'+p.id)?.requiresBankUpdate&&!readyExams.has('READ-'+p.id)?' disabled data-bank-check="READ-'+p.id+'"':''))+'</div>';}
function archive(){const names=['خالد بن الوليد واليرموك','عمر بن الخطاب والعدل','صلاح الدين','الحوت الأزرق','الزرافة','سالم والكتاب','الكهرباء','المياه سر الحياة','الألعاب الإلكترونية','التطوع'];return title('قراءات إضافية','مكتبة النصوص السابقة','اختر نصًا، واقرأه بتأن، ثم أجب عن أسئلته مستعينًا بما ورد فيه.')+'<div class="section-head"></div><div class="grid">'+names.map((n,i)=>'<article class="card"><h3>'+n+'</h3><a href="https://aass-2008-wq.github.io/nafis-text'+(i+1)+'/" target="_blank" rel="noopener" class="btn light">فتح النص السابق ↗</a></article>').join('')+'</div>';}
function notFound(){return '<div class="empty"><h1>الصفحة غير موجودة</h1><a href="#home">العودة للرئيسية</a></div>';}
function progress(){const mine=results.filter(r=>r.studentId===profile?.studentId);return title('أثر خطواتك','تقدمي في القراءة','نتائج مؤكدة محفوظة على هذا الجهاز. يحتفظ المعلم أيضًا بسجل المحاولات التي وصلت إليه.')+Object.values(drafts).filter(a=>a.profile.studentId===profile?.studentId).map(a=>'<div class="banner"><a href="'+quizLink(a)+'">استكمل '+esc(a.title)+' ←</a></div>').join('')+(!mine.length?'<div class="empty"><h2>نتيجتك الأولى تنتظرك</h2><p>بعد إكمال تدريب وإرسال نتيجته ستجد ملخصه هنا.</p><a class="btn" href="#exams">ابدأ القراءة</a></div>':'<div class="metrics"><div class="metric"><strong>'+ar(mine.length)+'</strong><span>محاولة محفوظة</span></div><div class="metric"><strong>'+ar(new Set(mine.map(x=>x.examId)).size)+'</strong><span>أنشطة جربتها</span></div><div class="metric"><strong>'+ar(mine[mine.length-1].percent)+'٪</strong><span>آخر نتيجة</span></div></div><div class="grid">'+mine.slice().reverse().map(r=>'<article class="card"><span class="badge">تم الحفظ</span><h3>'+esc(r.title||r.examId)+'</h3><p>'+when(r.submittedAt)+' · المحاولة '+ar(r.attemptNumber)+'</p><h2>'+ar(r.percent)+'٪</h2>'+btn('راجع الإجابات','data-result="'+r.attemptId+'"','light')+'</article>').join('')+'</div>');}
/* POST into a temporary iframe. Success is only an authenticated correlation reply,
   never a frame load or opaque fetch. Request nonce and teacher tokens are not URLs. */
function rpc(payload){return new Promise((resolve,reject)=>{if(location.origin!=='https://aass-2008-wq.github.io'){reject(new Error('هذه معاينة للتصميم. لتسجيل نتيجة، افتح النسخة المنشورة على موقع المدرسة بعد تفعيلها.'));return;}const requestId=uid(),frame=document.createElement('iframe'),form=document.createElement('form');frame.name='nafis-'+requestId;frame.hidden=true;frame.title='اتصال خدمة النتائج';form.method='POST';form.action=ENDPOINT;form.target=frame.name;form.hidden=true;for(const [name,value] of Object.entries({payload:JSON.stringify(payload),origin:location.origin,requestId})){const el=document.createElement('input');el.type='hidden';el.name=name;el.value=value;form.append(el);}let timer;const cleanup=()=>{clearTimeout(timer);window.removeEventListener('message',receive);form.remove();frame.remove();};const receive=e=>{if(!/^https:\/\/[a-z0-9.-]+\.googleusercontent\.com$/.test(e.origin)&&e.origin!=='https://script.google.com')return;const d=e.data;if(d?.channel!=='nafis-v2'||d.requestId!==requestId)return;cleanup();if(!d.response?.ok){const err=new Error(d.response?.code==='TEACHER_SETUP'?'لم يكتمل إعداد حساب المعلم.':d.response?.message||'تعذر تأكيد الطلب.');err.code=d.response?.code;reject(err);}else resolve(d.response);};window.addEventListener('message',receive);timer=setTimeout(()=>{cleanup();reject(new Error('لم يصل تأكيد من خدمة النتائج. تحقق من الاتصال ثم أعد المحاولة.'));},45000);document.body.append(frame,form);form.submit();});}
async function start(id){if(busy)return;if(!profile){profileForm(()=>start(id));return;}const exam=C.exams.find(e=>e.id===id);if(!exam||exam.kind==='simulation')return;if(exam.requiresBankUpdate&&!readyExams.has(id)){notify('الاختبار قيد الإعداد. يمكنك قراءة النص الآن.');return;}if(attempt&&!saveAttempt())return;const saved=savedAttempt(id);if(saved){attempt=saved;index=saved.questionIndex||0;location.hash=quizLink(saved);render();return;}openDialog('<h2>'+esc(exam.title)+'</h2><p>'+esc(profile.name)+' · '+esc(profile.classroom)+'</p><p>ستظهر الإجابات الصحيحة بعد إنهاء الاختبار وتأكيد حفظ النتيجة. يمكنك التنقل ومراجعة الإجابات قبل التسليم.</p><p class="hint">'+ar(exam.count)+' أسئلة · '+ar(exam.minutes)+' دقيقة مقترحة. يحفظ هذا الجهاز تقدمك للاستكمال.</p><p class="error" id="start-error"></p>'+btn('ابدأ الآن','id="confirm-start"','full'));$('#confirm-start').onclick=async()=>{busy=true;const previousAttempt=attempt,startProfile={...profile};$('#confirm-start').disabled=true;try{const r=await rpc({action:'start',...startProfile,examId:id,version:exam.version});if(r.examId!==id||r.version!==exam.version||!Array.isArray(r.questions)||!r.questions.length)throw new Error('تعذر فتح الاختبار المختار. أعد المحاولة.');attempt={...r,profile:startProfile,answers:{},flags:[],frozen:false,startedAt:Date.now(),minutes:exam.minutes};if(!saveAttempt()){attempt=previousAttempt;throw new Error('تعذر حفظ المحاولة على جهازك. فعّل تخزين بيانات الموقع ثم حاول مجددًا.');}index=0;dialog.close();location.hash=quizLink(attempt);render();}catch(e){if($('#start-error'))$('#start-error').textContent=e.message;if($('#confirm-start'))$('#confirm-start').disabled=false;}finally{busy=false;}};}
function quiz(id){if(id){attempt=savedAttempt(id)||null;index=attempt?.questionIndex||0;}if(!attempt)return '<div class="empty"><h2>لا توجد محاولة مفتوحة</h2><a class="btn" href="#exams">اختر نصًا</a></div>';if(attempt.frozen)return '<div class="empty"><span class="badge gold">الإجابات مقفلة</span><h1>ننتظر تأكيد حفظ نتيجتك</h1><p>حفظنا إجاباتك على هذا الجهاز. إعادة الإرسال تستخدم المحاولة نفسها ولا تغير إجاباتك.</p><p class="error" id="submit-error"></p>'+btn('إعادة إرسال النتيجة','id="retry"')+'</div>';index=Math.max(0,Math.min(index,attempt.questions.length-1));const q=attempt.questions[index],count=Object.keys(attempt.answers).length;return '<a class="quiz-back" href="'+returnLink(attempt)+'">→ العودة إلى '+(attempt.examId.startsWith('READ-')?'النص':'المهارات')+'</a><div class="quiz-top"><div><div class="eyebrow">'+esc(attempt.profile.name)+' · '+esc(attempt.profile.classroom)+'</div><h1>'+esc(attempt.title)+'</h1></div><div class="timer"><span id="clock">٠٠:٠٠</span><small>الوقت المنقضي · إرشادي</small></div></div><div class="quiz-layout"><article class="passage" aria-label="النص القرائي">'+paragraphs(questionPassage(attempt,q))+'</article><section class="question-panel"><div class="between"><span class="eyebrow">السؤال '+ar(index+1)+' من '+ar(attempt.questions.length)+'</span><button class="text-btn" id="flag">'+(attempt.flags.includes(q.id)?'★ معلّم للمراجعة':'☆ علّم للمراجعة')+'</button></div><div class="progress-track"><span style="width:'+count/attempt.questions.length*100+'%"></span></div><h2 id="question-title" tabindex="-1">'+esc(q.question)+'</h2><fieldset style="border:0;padding:0;margin:0"><legend class="hint">اختر إجابة واحدة</legend><div class="options">'+q.choices.map((c,i)=>'<label class="option"><input type="radio" name="answer" value="'+(i+1)+'" '+(attempt.answers[q.id]===i+1?'checked':'')+'><span>'+esc(c)+'</span></label>').join('')+'</div></fieldset><div class="actions" style="margin-top:22px">'+btn('→ السابق','id="prev" '+(index===0?'disabled':''),'light')+btn(index===attempt.questions.length-1?'مراجعة وتسليم':'التالي ←','id="next"')+'</div><div class="quiz-nav" aria-label="أرقام الأسئلة">'+attempt.questions.map((x,i)=>'<button class="q-dot '+(attempt.answers[x.id]?'answered ':'')+(i===index?'current ':'')+(attempt.flags.includes(x.id)?'flagged':'')+'" data-q="'+i+'" aria-label="السؤال '+(i+1)+(attempt.answers[x.id]?' مجاب':' غير مجاب')+(attempt.flags.includes(x.id)?' للمراجعة':'')+'" '+(i===index?'aria-current="step"':'')+'>'+ar(i+1)+'</button>').join('')+'</div><p class="hint">المجاب '+ar(count)+' / '+ar(attempt.questions.length)+' · النقطة الذهبية: للمراجعة</p>'+btn('إنهاء الاختبار وإرسال النتيجة','id="finish"','full')+'<button id="leave" class="text-btn">حفظ والعودة لاحقًا</button></section></div>';}
function saveAttempt(){if(!attempt)return true;try{const next={...read('nafis-drafts-v3',drafts),[draftKey(attempt)]:attempt};write('nafis-drafts-v3',next);drafts=next;return true;}catch{notify('تعذر حفظ التغيير على الجهاز؛ تحقق من مساحة التخزين.');return false;}}
function confirmFinish(){const left=attempt.questions.length-Object.keys(attempt.answers).length;openDialog('<h2>هل أنت مستعد للتسليم؟</h2><p>'+(left?'بقي '+ar(left)+' سؤالًا دون إجابة. ستحتسب الأسئلة المتروكة غير صحيحة.':'أجبت عن جميع الأسئلة.')+'</p><p>بعد التسليم تقفل الإجابات، وتظهر النتيجة بعد تأكيد الحفظ لدى المعلم.</p><div class="actions">'+btn('تأكيد الإنهاء والإرسال','id="submit-final"')+btn('أعود للمراجعة','id="cancel-submit"','light')+'</div>');$('#cancel-submit').onclick=()=>dialog.close();$('#submit-final').onclick=()=>{attempt.frozen=true;if(!saveAttempt()){attempt.frozen=false;return;}dialog.close();render();sendAttempt();};}
async function sendAttempt(){if(busy||!attempt)return;busy=true;const sent=attempt;const b=$('#retry');if(b)b.disabled=true;try{const r=await rpc({action:'submit',attemptId:sent.attemptId,token:sent.token,answers:sent.answers});if(r.attemptId!==sent.attemptId||!Array.isArray(r.review))throw new Error('وصل رد غير مكتمل. أعد الإرسال للتحقق.');const stored={...r,title:sent.title,studentId:sent.profile.studentId};const nextResults=results.filter(x=>x.attemptId!==r.attemptId).concat(stored);write('nafis-results-v2',nextResults);const remaining={...read('nafis-drafts-v3',drafts)};delete remaining[draftKey(sent)];write('nafis-drafts-v3',remaining);drafts=remaining;localStorage.removeItem('nafis-active-v2');results=nextResults;if(attempt?.attemptId===sent.attemptId)attempt=null;location.hash='#result/'+r.attemptId;render();}catch(e){if($('#submit-error'))$('#submit-error').textContent=e.message;if($('#retry'))$('#retry').disabled=false;}finally{busy=false;}}
function resultView(id){const r=results.find(x=>x.attemptId===id&&x.studentId===profile?.studentId);if(!r)return notFound();const weakest=r.skills.filter(s=>s.correct<s.total).sort((a,b)=>a.percent-b.percent)[0];return '<section class="score"><span class="badge">تم تأكيد حفظ النتيجة</span><h1>'+esc(r.title||r.examId)+'</h1><div class="big">'+ar(r.percent)+'٪</div><p>'+ar(r.correct)+' إجابات صحيحة من '+ar(r.total)+' · المحاولة '+ar(r.attemptNumber)+'</p><small>وصلت النتيجة إلى سجل المعلم بتاريخ '+when(r.submittedAt)+'</small></section><div class="actions"><a class="btn light" href="#progress">عرض تقدمي</a>'+'<a class="btn" href="#exams">محاكاة أخرى</a>'+'</div><div class="section-head"><div><h2>ما الذي تعلمته؟</h2><p>كل خطأ يرشدك إلى خطوة التدريب التالية.</p></div></div><div class="grid skill-grid">'+r.skills.map(s=>'<article class="card"><h3>'+esc(s.skill)+'</h3><strong>'+ar(s.correct)+' / '+ar(s.total)+'</strong><p>'+(s.total<5?'أسئلة محدودة؛ هذه نتيجة تدريب وليست حكم إتقان.':'راجع الإجابات لتتعرف على مواضع التحسن.')+'</p></article>').join('')+'</div><div class="section-head"><h2>مراجعة الإجابات</h2></div>'+r.review.map(reviewRow).join('');}
function reviewRow(q,i){return '<article class="review-row '+(q.isCorrect?'correct':'wrong')+'"><span class="badge '+(q.isCorrect?'':'red')+'">'+(q.isCorrect?'صحيح':q.chosen===null?'لم تجب':'تحتاج مراجعة')+'</span> <span class="hint">'+esc(q.skill)+'</span><h3>'+ar(i+1)+'. '+esc(q.question)+'</h3><p>إجابتك: '+esc(q.chosenText)+'</p>'+(!q.isCorrect?'<p><strong>الإجابة الصحيحة: '+esc(q.correctText)+'</strong></p>':'')+'<p class="hint">'+esc(q.explanation)+'</p></article>';}
function normalizeTeacherKey(value){return value.replace(/[\s\u200B-\u200F\u202A-\u202E\u2060-\u2069\uFEFF]/g,'').replace(/[\u2010-\u2015\u2212\uFE63\uFF0D]/g,'-');}
function teacher(){if(!teacherSession)return title('محاكي نافس المطور · التحديث ٢','لوحة المعلم','النتائج والتقارير')+'<form class="login" id="teacher-login"><h2>دخول المعلم</h2><div class="field"><label for="teacher-key">مفتاح المعلم</label><input id="teacher-key" type="password" required autocomplete="current-password" autocapitalize="none" spellcheck="false" dir="ltr"></div><p class="error" id="login-error"></p>'+btn('الدخول إلى التقارير','type="submit"','full')+'</form>';return title('محاكي نافس المطور · التحديث ٢','لوحة المعلم','الطلاب · المحاولات · المهارات')+'<div class="actions" style="margin-top:20px">'+btn(icon('refresh')+'تحديث النتائج','id="refresh-report"')+btn(icon('exit')+'خروج','id="teacher-logout"','light')+'</div><div class="filters"><div class="field"><label for="class-filter">الفصل</label><select id="class-filter"><option value="">جميع الفصول</option>'+[...new Set(report.map(r=>r.classroom))].sort().map(v=>'<option>'+esc(v)+'</option>').join('')+'</select></div><div class="field"><label for="student-filter">الطالب</label><select id="student-filter"><option value="">جميع الطلاب</option>'+[...new Map(report.map(r=>[r.studentId,r])).values()].sort((a,b)=>a.name.localeCompare(b.name,'ar')).map(r=>'<option value="'+esc(r.studentId)+'">'+esc(r.name)+' — '+esc(r.classroom)+' ('+esc(r.studentId)+')</option>').join('')+'</select></div><div class="field"><label for="name-filter">اسم الطالب أو رمزه</label><input id="name-filter" type="search" placeholder="ابحث عن طالب"></div><div class="field"><label for="exam-filter">النشاط</label><select id="exam-filter"><option value="">جميع الأنشطة</option>'+C.exams.map(e=>'<option value="'+e.id+'">'+esc(e.title)+'</option>').join('')+'</select></div><div class="field"><label for="skill-filter">المهارة</label><select id="skill-filter"><option value="">جميع المهارات</option>'+C.skills.map(s=>'<option value="'+s.id+'">'+esc(s.label)+'</option>').join('')+'</select></div></div><div id="report-body"></div>';}
function reportSelection(){return {classroom:$('#class-filter').value,name:$('#name-filter').value.trim(),studentId:$('#student-filter').value,examId:$('#exam-filter').value,skillId:$('#skill-filter').value,details:$('#report-details')?.checked!==false};}
function collectReport(rows,f){
 const filtered=rows.filter(r=>(!f.classroom||r.classroom===f.classroom)&&(!f.studentId||r.studentId===f.studentId)&&(!f.name||r.name.includes(f.name)||r.studentId.includes(f.name))&&(!f.examId||r.result.examId===f.examId)).slice().sort((a,b)=>new Date(a.result.submittedAt)-new Date(b.result.submittedAt));
 const groups=new Map(),seen=new Set();
 for(const r of filtered)for(const q of r.result.review){
  const key=JSON.stringify([r.studentId,r.result.version,q.questionId]);if(seen.has(key))continue;seen.add(key);if(f.skillId&&q.skillId!==f.skillId)continue;
  const k=JSON.stringify([r.studentId,q.skillId]),g=groups.get(k)||{studentId:r.studentId,name:r.name,classroom:r.classroom,skillId:q.skillId,skill:q.skill,total:0,correct:0,unanswered:0};
  g.total++;if(q.isCorrect)g.correct++;if(q.chosen===null)g.unanswered++;groups.set(k,g);
 }
 const groupsList=[...groups.values()].sort((a,b)=>a.name.localeCompare(b.name,'ar')||a.studentId.localeCompare(b.studentId)||a.skill.localeCompare(b.skill,'ar'));
 return {filtered,groups:groupsList};
}
function skillTable(gs){return '<table class="skills-table"><colgroup><col style="width:28%"><col style="width:10%"><col style="width:22%"><col span="5" style="width:8%"></colgroup><thead><tr><th>الطالب</th><th>الفصل</th><th>المهارة</th><th>صحيح</th><th>خطأ</th><th>لم يجب</th><th>الأسئلة</th><th>النسبة</th></tr></thead><tbody>'+gs.map(g=>'<tr><td class="student-cell" dir="rtl"><span class="student-name">'+esc(g.name)+'</span><br><small><bdi dir="ltr">'+esc(g.studentId)+'</bdi></small></td><td>'+esc(g.classroom)+'</td><td>'+esc(g.skill)+'</td><td>'+ar(g.correct)+'</td><td>'+ar(g.total-g.correct-g.unanswered)+'</td><td>'+ar(g.unanswered)+'</td><td>'+ar(g.total)+'</td><td>'+ar(Math.round(g.correct/g.total*100))+'٪</td></tr>').join('')+'</tbody></table>';}
function remedialPlan(gs){
 const activities={vocabulary:'قراءة الكلمة في سياقها، وتحديد معناها ومرادفها وضدها، ثم توظيفها في جملة.',direct:'تحديد الكلمات المفتاحية في السؤال، والعودة إلى النص لاستخراج المعلومة وتحديد موضعها.',main:'تلخيص كل فقرة في جملة، ثم اختيار الفكرة الرئيسة وتمييزها من التفاصيل.',inference:'استخراج قرينتين من النص، ثم صياغة استنتاج وتبريره بالدليل.',relations:'تنظيم أحداث النص، وربط الأسباب بالنتائج، وإجراء مقارنة بين فكرتين.',purpose:'تحديد هدف الكاتب من النص، مع الاستشهاد بعبارة تدعم الاختيار.',evaluation:'التمييز بين الحقيقة والرأي، ومناقشة قوة الدليل الذي يدعم كل ادعاء.',application:'تطبيق فكرة النص على موقف جديد، وشرح وجه الارتباط بينهما.'};
 const weak=gs.filter(g=>g.correct<g.total);
 if(!weak.length)return '<section class="remedial-plan"><h2>متابعة وتعزيز</h2><p>لم تظهر أخطاء في المهارات المشمولة بهذا التقرير. يواصل الطالب قراءة نصوص متنوعة وتطبيق مهارات الفهم عليها.</p></section>';
 return '<section class="remedial-plan"><h2>خطة علاجية للمهارات غير المتقنة</h2><p>الهدف: تحسين أداء الطالب في المهارات التي ظهرت فيها أخطاء أو إجابات متروكة. التنفيذ المقترح: ثلاث جلسات قصيرة خلال أسبوع، ثم تقويم المتابعة.</p><div class="report-scroll"><table class="remedial-table"><colgroup><col style="width:28%"><col style="width:17%"><col style="width:30%"><col style="width:25%"></colgroup><thead><tr><th>الطالب</th><th>المهارة المستهدفة</th><th>النشاط العلاجي</th><th>تقويم المتابعة</th></tr></thead><tbody>'+weak.map(g=>'<tr><td class="student-cell" dir="rtl"><span class="student-name">'+esc(g.name)+'</span><br><small><bdi dir="ltr">'+esc(g.studentId)+'</bdi></small></td><td>'+esc(g.skill)+'</td><td>'+esc(activities[g.skillId]||'إعادة قراءة النص، ومناقشة موضع الخطأ، ثم التدريب على أسئلة جديدة في المهارة.')+'</td><td>حل خمسة أسئلة جديدة في المهارة، ومناقشة الإجابات وتسجيل مقدار التحسن.</td></tr>').join('')+'</tbody></table></div></section>';
}
function questionEvidence(rows,f,studentId){const filtered=collectReport(rows,f).filtered.filter(r=>r.studentId===studentId),seen=new Set(),out=[];for(const r of filtered)for(const q of r.result.review){const key=JSON.stringify([r.result.version,q.questionId]);if(seen.has(key))continue;seen.add(key);if(f.skillId&&f.skillId!==q.skillId)continue;out.push({...q,examTitle:C.exams.find(e=>e.id===r.result.examId)?.title||r.result.examId,name:r.name,studentId:r.studentId,classroom:r.classroom});}return out;}
function reportSkills(gs){return '<table class="report-skills"><colgroup><col style="width:40%"><col span="4" style="width:15%"></colgroup><thead><tr><th>المهارة</th><th>صحيح</th><th>خطأ</th><th>لم يجب</th><th>النسبة</th></tr></thead><tbody>'+gs.map(g=>'<tr><td>'+esc(g.skill)+'</td><td>'+ar(g.correct)+' / '+ar(g.total)+'</td><td>'+ar(g.total-g.correct-g.unanswered)+'</td><td>'+ar(g.unanswered)+'</td><td>'+ar(Math.round(g.correct/g.total*100))+'٪</td></tr>').join('')+'</tbody></table>';}
function reportQuestions(qs){if(!qs.length)return '';return '<section class="report-section"><h3>الأسئلة والمهارات</h3>'+qs.map((q,i)=>'<article class="report-question"><div class="report-question-top"><span>'+ar(i+1)+' · '+esc(q.skill)+'</span><strong class="'+(q.isCorrect?'answer-correct':'answer-wrong')+'">'+(q.isCorrect?'صحيح':q.chosen===null?'لم يجب':'غير صحيح')+'</strong></div><h4>'+esc(q.question)+'</h4><div class="report-answer"><p>إجابة الطالب: '+esc(q.chosenText||'لم يجب')+'</p><p>الإجابة الصحيحة: '+esc(q.correctText)+'</p></div><small>'+esc(q.examTitle)+'</small></article>').join('')+'</section>';}
function reportPlan(gs){const activities={vocabulary:'تحديد معنى الكلمة من سياقها، وذكر مرادفها وضدها، وتوظيفها في جملة.',direct:'تحديد موضع المعلومة في النص وربطها بالكلمات المفتاحية في السؤال.',main:'تلخيص الفقرات وتحديد الفكرة الرئيسة وتمييزها من التفاصيل.',inference:'استخراج قرينتين وصياغة استنتاج تدعمهما.',relations:'تنظيم الأحداث وربط الأسباب بالنتائج والمقارنة بين الأفكار.',purpose:'تحديد غرض الكاتب مع شاهد من النص.',evaluation:'تمييز الحقيقة من الرأي ومقارنة الادعاء بالدليل.',application:'تطبيق فكرة النص على موقف جديد وتوضيح العلاقة.'};const weak=gs.filter(g=>g.correct<g.total);return '<section class="report-section"><h3>'+(weak.length?'خطة علاجية للمهارات غير المتقنة':'متابعة وتعزيز')+'</h3>'+(weak.length?'<p class="plan-duration">المدة: أسبوع · ثلاث جلسات قصيرة · تقويم المتابعة: خمسة أسئلة جديدة لكل مهارة</p>'+weak.map(g=>'<div class="plan-item"><strong>'+esc(g.skill)+'</strong><p>'+esc(activities[g.skillId]||'قراءة إضافية وتدريب على المهارة.')+'</p></div>').join(''):'<p>مواصلة القراءة المتنوعة والتدريب على مهارات الفهم.</p>')+'</section>';}
function reportMarkup(gs,f,rows=report){const students=[...new Set(gs.map(g=>g.studentId))];return '<div class="report-pages">'+students.map(id=>{const group=gs.filter(g=>g.studentId===id),g=group[0],qs=questionEvidence(rows,f,id),total=group.reduce((n,g)=>n+g.total,0),correct=group.reduce((n,g)=>n+g.correct,0);return '<section class="school-report"><header class="report-letterhead"><img src="'+new URL('assets/moe.svg',document.baseURI).href+'" alt="شعار وزارة التعليم"><div><p>المملكة العربية السعودية · وزارة التعليم<br>الإدارة العامة للتعليم بالقصيم<br>مدرسة الإمام الشوكاني الابتدائية بالمذنب</p><h1>تقرير مهارات الطالب</h1><p>محاكي نافس المطور · النسخة الثانية · التحديث ٢</p></div><img src="'+new URL('assets/school.webp',document.baseURI).href+'" alt="شعار المدرسة"></header><div class="report-student"><span>اسم الطالب</span><h2 class="student-name" dir="rtl">'+esc(g.name)+'</h2><div class="student-meta"><span>الفصل: '+esc(g.classroom)+'</span><span>رمز الطالب: <bdi dir="ltr">'+esc(id)+'</bdi></span><span>التاريخ: '+esc(new Date().toLocaleDateString('ar-SA'))+'</span></div></div><div class="report-stats"><div><strong>'+ar(total)+'</strong><span>سؤالًا</span></div><div><strong>'+ar(correct)+'</strong><span>إجابة صحيحة</span></div><div><strong>'+ar(Math.round(correct/total*100))+'٪</strong><span>نسبة الإجابات الصحيحة</span></div></div><section class="report-section"><h3>المهارات</h3>'+reportSkills(group)+'</section>'+reportPlan(group)+(f.details===false?'':reportQuestions(qs))+'<div class="report-signature">إعداد الأستاذ مقرن المطيري</div></section>';}).join('')+'</div>';}
const REPORT_CSS=`
*{box-sizing:border-box}.report-pages{direction:rtl;color:#123d49;font-family:Arial,Tajawal,sans-serif;line-height:1.7;text-align:right}.school-report{max-width:780px;margin:0 auto 24px;background:#fff;padding:24px;overflow:visible;direction:rtl}.report-letterhead{display:grid;grid-template-columns:72px minmax(0,1fr) 72px;align-items:center;gap:14px;text-align:center;border-bottom:2px solid #087f80;padding-bottom:14px}.report-letterhead img{width:72px;height:72px;object-fit:contain}.report-letterhead p{font-size:11px;margin:4px 0}.report-letterhead h1{font-size:22px;margin:8px 0;line-height:1.5}.report-student{background:#eef4f0;padding:16px;margin:20px 0;border-radius:10px}.report-student>span{font-size:12px;color:#536c72}.school-report .student-name{display:block;font-size:22px;font-weight:bold;line-height:1.8;margin:2px 0 8px;direction:rtl;unicode-bidi:plaintext;white-space:normal;word-break:normal;overflow-wrap:normal;letter-spacing:normal;hyphens:none;width:auto;max-width:none}.student-meta{display:flex;gap:8px 20px;flex-wrap:wrap;font-size:12px}.student-meta bdi{white-space:nowrap}.report-stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.report-stats>div{border:1px solid #dce5e0;padding:10px;text-align:center;border-radius:8px}.report-stats strong{display:block;font-size:24px;color:#087f80}.report-stats span{display:block;font-size:11px}.report-section{margin-top:22px}.report-section h3{font-size:17px;margin:0 0 10px;break-after:avoid}.school-report table{border-collapse:collapse;table-layout:fixed;width:100%;min-width:0!important;white-space:normal;font-size:12px}.school-report th,.school-report td{border:1px solid #dce5e0;padding:8px;text-align:right;vertical-align:top;word-break:normal;overflow-wrap:normal;white-space:normal!important;letter-spacing:normal}.school-report th{background:#eef4f0}.school-report tr{break-inside:avoid}.school-report thead{display:table-header-group}.plan-duration{font-size:12px}.plan-item{border-inline-start:3px solid #c8a561;padding:8px 12px;background:#fbf8f0;margin:8px 0;break-inside:avoid}.plan-item strong{font-size:13px}.plan-item p{font-size:12px;margin:3px 0}.report-question{border:1px solid #dce5e0;border-radius:8px;padding:12px;margin:10px 0;break-inside:avoid}.report-question-top{display:flex;justify-content:space-between;gap:12px;font-size:11px}.report-question h4{font-size:13px;margin:6px 0;line-height:1.8;font-weight:bold}.report-answer{display:grid;grid-template-columns:1fr 1fr;gap:12px}.report-answer p{font-size:11px;margin:3px 0}.report-question small{font-size:10px;color:#536c72}.answer-correct{color:#28644c}.answer-wrong{color:#994444}.report-signature{margin-top:20px;border-top:1px solid #dce5e0;padding-top:10px;font-size:12px;text-align:left}.school-report p{word-break:normal;overflow-wrap:normal;letter-spacing:normal}@media screen and (max-width:600px){.school-report{padding:14px}.report-letterhead{grid-template-columns:52px minmax(0,1fr) 52px;gap:8px}.report-letterhead img{width:52px;height:52px}.report-letterhead p{font-size:9px}.report-letterhead h1{font-size:17px}.school-report .student-name{font-size:19px}.school-report th,.school-report td{padding:6px;font-size:11px}.report-answer{grid-template-columns:1fr;gap:2px}.report-stats strong{font-size:21px}}@page{size:A4 portrait;margin:12mm}@media print{html,body{width:auto!important;min-width:0!important;max-width:none!important;margin:0!important;padding:0!important;overflow:visible!important;background:white!important;-webkit-text-size-adjust:100%;text-size-adjust:100%}.report-pages{width:auto!important}.school-report{width:auto!important;max-width:none!important;min-width:0!important;margin:0!important;padding:0!important;break-after:page}.school-report:last-child{break-after:auto}.report-letterhead{grid-template-columns:64px minmax(0,1fr) 64px}.report-letterhead img{width:64px;height:64px}.report-letterhead h1{font-size:18pt}.report-letterhead p{font-size:8pt}.school-report .student-name{font-size:16pt}.school-report td,.school-report th{font-size:9pt}.report-student{break-inside:avoid}.report-stats{break-inside:avoid}.report-question{box-shadow:none}.report-question h4{font-size:10pt}.report-answer p{font-size:9pt}.plan-item p{font-size:9pt}.report-section{break-inside:auto}.report-signature{break-inside:avoid}}`;
function reportDocument(gs,f,rows=report){return '<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>تقرير مهارات الطالب — محاكي نافس المطور</title><style>body{margin:0;background:#f4f7f5}'+REPORT_CSS+'</style></head><body>'+reportMarkup(gs,f,rows)+'</body></html>';}

function csvCell(value){let s=String(value??'');if(/^[\s\u200b-\u200f\u202a-\u202e\u2060-\u2069\ufeff]*[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
function reportCSV(gs){const rows=[['اسم الطالب','رمز الطالب','الفصل','المهارة','صحيح','خطأ','لم يجب','عدد الأسئلة','النسبة المئوية'],...gs.map(g=>[g.name,g.studentId,g.classroom,g.skill,g.correct,g.total-g.correct-g.unanswered,g.unanswered,g.total,Math.round(g.correct/g.total*100)])];return '\uFEFF'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n');}
async function reportWithLogos(gs,f){
 let html=reportDocument(gs,f);
 for(const path of ['assets/moe.svg','assets/school.webp']){
  const url=new URL(path,document.baseURI).href,response=await fetch(url);if(!response.ok)throw new Error('تعذر تحميل شعار التقرير. تحقق من الاتصال وأعد المحاولة.');
  const blob=await response.blob(),data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);});
  html=html.replace(esc(url),data);
 }
 return html;
}
async function downloadReport(kind){if(!teacherSession)return;const f=reportSelection(),gs=collectReport(report,f).groups;if(!gs.length){notify('لا توجد نتائج لتنزيلها ضمن الاختيار الحالي.');return;}
 const button=$(kind==='html'?'#download-report':'#download-csv'),session=teacherSession;button.disabled=true;
 try{const html=kind==='html',content=html?await reportWithLogos(gs,f):reportCSV(gs);if(session!==teacherSession)return;
 const blob=new Blob([content],{type:html?'text/html;charset=utf-8':'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Nafis-'+(f.studentId||'students')+'-'+new Date().toISOString().slice(0,10)+(html?'.html':'.csv');document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);
 }catch{notify('تعذر تنزيل التقرير. تحقق من الاتصال ثم حاول مجددًا.');}finally{if(button.isConnected)button.disabled=false;}
}
async function printTeacherReport(){if(!teacherSession)return;const f=reportSelection(),gs=collectReport(report,f).groups;if(!gs.length)return;$('#print-report-root')?.remove();const root=document.createElement('div');root.id='print-report-root';root.innerHTML='<style>'+REPORT_CSS+'</style>'+reportMarkup(gs,f);document.body.append(root);document.body.classList.add('printing-report');try{await Promise.all([...root.querySelectorAll('img')].map(img=>img.decode()));window.print();}catch{document.body.classList.remove('printing-report');root.remove();notify('تعذر تحميل شعارات التقرير. أعد المحاولة.');}}
window.addEventListener('afterprint',()=>{document.body.classList.remove('printing-report');$('#print-report-root')?.remove();});
function drawReport(){const f=reportSelection(),{filtered,groups:gs}=collectReport(report,f),skill=f.skillId;
 $('#report-body').innerHTML='<div class="metrics"><div class="metric"><strong>'+ar(new Set(gs.map(r=>r.studentId)).size)+'</strong><span>طلاب ضمن الاختيار</span></div><div class="metric"><strong>'+ar(filtered.length)+'</strong><span>محاولات مسلمة</span></div><div class="metric"><strong>'+ar(gs.reduce((s,g)=>s+g.total-g.correct,0))+'</strong><span>إجابات تحتاج متابعة</span></div></div><section class="report-tools"><h2>تقارير الطلاب</h2><label class="report-option"><input type="checkbox" id="report-details" checked> تفاصيل الأسئلة والمهارات</label><div class="actions">'+btn(icon('download')+'تنزيل التقرير','id="download-report" '+(!gs.length?'disabled':''))+btn(icon('chart')+'تنزيل جدول CSV','id="download-csv" '+(!gs.length?'disabled':''),'light')+btn(icon('print')+'طباعة / حفظ PDF','id="print-report" '+(!gs.length?'disabled':''),'light')+'</div></section>'+(!gs.length?'<div class="empty"><h2>لا توجد نتائج ضمن هذا الاختيار</h2><p>تظهر النتائج بعد تسليم الطلاب لمحاولاتهم.</p></div>':'<div class="section-head"><h2>نتائج الطلاب حسب المهارة</h2></div><div class="table-wrap">'+skillTable(gs)+'</div>')+(!filtered.length?'':'<div class="section-head"><h2>سجل المحاولات</h2></div><div class="table-wrap"><table><thead><tr><th>الطالب</th><th>النشاط</th><th>المحاولة</th><th>الدرجة</th><th>التاريخ</th><th>التفاصيل</th></tr></thead><tbody>'+filtered.slice().reverse().map(r=>'<tr><td>'+esc(r.name)+'</td><td>'+esc(C.exams.find(e=>e.id===r.result.examId)?.title||r.result.examId)+'</td><td>'+ar(r.result.attemptNumber)+'</td><td>'+ar(r.result.percent)+'٪</td><td>'+when(r.result.submittedAt)+'</td><td>'+btn('الإجابات','data-detail="'+r.result.attemptId+'"','light')+'</td></tr>').join('')+'</tbody></table></div>');
 $('#download-report').onclick=()=>downloadReport('html');$('#download-csv').onclick=()=>downloadReport('csv');$('#print-report').onclick=printTeacherReport;
 $('#report-body').querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{const r=report.find(r=>r.result.attemptId===b.dataset.detail);openDialog('<h2>'+esc(r.name)+'</h2><p>'+esc(r.classroom)+' · المحاولة '+ar(r.result.attemptNumber)+'</p>'+r.result.review.filter(q=>!skill||q.skillId===skill).map(reviewRow).join(''));});
}
async function loadReport(){const seq=++routeSeq;main.innerHTML='<div class="loading">جارٍ قراءة النتائج المؤكدة…</div>';try{let offset=0,rows=[];do{const r=await rpc({action:'teacherReport',session:teacherSession,offset});rows=rows.concat(r.rows);offset=r.nextOffset;}while(offset!==null);if(seq!==routeSeq)return;report=rows;render();}catch(e){if(seq!==routeSeq)return;if(e.code==='AUTH_EXPIRED'){teacherSession=null;report=[];render();notify(e.message);}else main.innerHTML='<div class="empty"><h2>تعذر تحميل التقارير</h2><p>'+esc(e.message)+'</p>'+btn('إعادة المحاولة','id="reload-report"')+'</div>';if($('#reload-report'))$('#reload-report').onclick=loadReport;}}
function wire(){checkReadingReady();if($('#word-list')){drawWords();$('#word-search').oninput=drawWords;document.querySelectorAll('[data-word-kind]').forEach(b=>b.onclick=()=>{wordKind=b.dataset.wordKind;drawWords();});}if($('#run-check'))$('#run-check').onclick=runCheck;document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>start(b.dataset.start));document.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>{if(attempt&&!saveAttempt())return;profileForm(()=>{attempt=null;render();});});document.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>location.hash='#result/'+b.dataset.result);
if($('#retry'))$('#retry').onclick=sendAttempt;if($('#finish')){const current=attempt.questions[index];document.querySelectorAll('input[name=answer]').forEach(el=>el.onchange=()=>{const old=attempt.answers[current.id];attempt.answers[current.id]=Number(el.value);if(!saveAttempt()){if(old===undefined)delete attempt.answers[current.id];else attempt.answers[current.id]=old;}const scroll=window.scrollY;render();window.scrollTo(0,scroll);});$('#prev').onclick=()=>{index--;attempt.questionIndex=index;saveAttempt();render();$('#question-title').focus();};$('#next').onclick=()=>{if(index===attempt.questions.length-1)confirmFinish();else{index++;attempt.questionIndex=index;saveAttempt();render();$('#question-title').focus();}};$('#flag').onclick=()=>{attempt.flags=attempt.flags.includes(current.id)?attempt.flags.filter(x=>x!==current.id):attempt.flags.concat(current.id);saveAttempt();render();};document.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>{index=Number(b.dataset.q);attempt.questionIndex=index;saveAttempt();render();$('#question-title').focus();});$('#finish').onclick=confirmFinish;$('#leave').onclick=()=>{if(saveAttempt())location.hash=returnLink(attempt);};const updateClock=()=>{const seconds=Math.max(0,Math.floor((Date.now()-attempt.startedAt)/1000));if($('#clock'))$('#clock').textContent=ar(Math.floor(seconds/60))+':'+String(seconds%60).padStart(2,'0');};updateClock();tick=setInterval(updateClock,1000);}
if($('#teacher-login'))$('#teacher-login').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const r=await rpc({action:'teacherLogin',key:normalizeTeacherKey($('#teacher-key').value)});$('#teacher-key').value='';teacherSession=r.session;await loadReport();}catch(err){if($('#login-error'))$('#login-error').textContent=err.message;if(button)button.disabled=false;}};
if($('#report-body')){drawReport();['class-filter','name-filter','student-filter','exam-filter','skill-filter'].forEach(id=>$('#'+id).oninput=drawReport);$('#refresh-report').onclick=loadReport;$('#teacher-logout').onclick=async()=>{const session=teacherSession;teacherSession=null;report=[];$('#print-report-root')?.remove();document.body.classList.remove('printing-report');render();try{await rpc({action:'teacherLogout',session});}catch{};};}}
function checkConnection(){return title('فحص خاص بالتشغيل','فحص خدمة النتائج','فحص تقني يستخدم محاولة تجريبية مستبعدة من تقارير الطلاب.')+'<div class="notice">يتحقق الفحص من الاتصال وحفظ إجابات تجريبية وثبات النتيجة عند تكرار الإرسال.</div>'+btn('تشغيل الفحص','id="run-check"')+'<div id="check-log" role="status" aria-live="polite"></div>';}
async function runCheck(){const b=$('#run-check');b.disabled=true;const log=$('#check-log');const add=t=>{const p=document.createElement('p');p.textContent=t;log.append(p);};try{const ping=await rpc({action:'ping'});if(ping.version!=='2')throw new Error('النشر لا يشغل الإصدار الجديد بعد.');add('✓ تم الاتصال بالإصدار ٢.');const a=await rpc({action:'start',studentId:'DEMO-'+uid(),name:'فحص تقني للربط',classroom:'فحص تقني',examId:'DEMO-01',version:'1'});add('✓ بدأت المحاولة دون كشف الإجابات.');if(a.questions.some(q=>'correct' in q||'explanation' in q))throw new Error('تم كشف مفاتيح إجابة قبل التسليم.');const r=await rpc({action:'submit',attemptId:a.attemptId,token:a.token,answers:{q1:1,q2:1,q3:null,q4:1}});if(r.percent!==50)throw new Error('نتيجة الفحص غير متوقعة.');add('✓ حُفظت النتيجة التجريبية: ٥٠٪.');const duplicate=await rpc({action:'submit',attemptId:a.attemptId,token:a.token,answers:{q1:1,q2:2,q3:3,q4:1}});if(duplicate.percent!==50||!duplicate.duplicate)throw new Error('لم يثبت الاختبار نتيجة التسليم.');add('✓ بقيت النتيجة الأولى رغم تغيير الإجابات في إعادة الإرسال.');const stored=await rpc({action:'result',attemptId:a.attemptId,token:a.token});if(stored.percent!==50)throw new Error('تعذر استرجاع النتيجة المحفوظة.');add('✓ نجح فحص الحفظ والاسترجاع.');}catch(e){add('تعذر إكمال الفحص: '+e.message);}finally{b.disabled=false;}}
function render(){clearInterval(tick);const route=(location.hash||'#home').slice(1),[page,arg]=route.split('/');document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+page));main.innerHTML=page==='home'?home():page==='exams'?readings():page==='past-exams'?pastExams():page==='skills'?readings():page==='words'?words():page==='readings'?readings():page==='read'?reader(arg):page==='archive'?archive():page==='quiz'?quiz(arg):page==='progress'?progress():page==='result'?resultView(arg):page==='teacher'?teacher():page==='check'?checkConnection():notFound();wire();}
window.addEventListener('hashchange',()=>{routeSeq++;render();window.scrollTo({top:0,behavior:'instant'});});
window.addEventListener('storage',e=>{if(e.key==='nafis-drafts-v3'){drafts=read('nafis-drafts-v3',{});attempt=attempt?savedAttempt(attempt.examId)||null:null;results=read('nafis-results-v2',[]);render();}});
render();
